std::string computeOValue(std::string const& user_password, std::string const& owner_password, QPDF::EncryptionData const& data) {
    // Derive an RC4 key from the user and owner passwords
    unsigned char rc4_key[16];
    std::string combined_password = user_password + owner_password;
    SHA1_CTX sha1;
    SHA1Init(&sha1);
    SHA1Update(&sha1, reinterpret_cast<const unsigned char*>(combined_password.c_str()), combined_password.size());
    SHA1Final(rc4_key, &sha1);

    // Pad or truncate the user password
    std::string padded_user_password = user_password;
    if (padded_user_password.size() < data.key_length) {
        padded_user_password.resize(data.key_length, '\0');
    } else if (padded_user_password.size() > data.key_length) {
        padded_user_password.resize(data.key_length);
    }

    // Convert the padded user password into bytes
    unsigned char user_password_bytes[data.key_length];
    std::memcpy(user_password_bytes, padded_user_password.c_str(), data.key_length);

    // Initialize the RC4 state
    unsigned char rc4_state[256];
    for (unsigned int i = 0; i < 256; ++i) {
        rc4_state[i] = i;
    }

    unsigned int j = 0;
    for (unsigned int i = 0; i < 256; ++i) {
        j = (j + rc4_state[i] + rc4_key[i % 16]) % 256;
        std::swap(rc4_state[i], rc4_state[j]);
    }

    // Iterate the RC4 algorithm
    unsigned int i = 0, j = 0;
    for (unsigned int k = 0; k < data.key_length; ++k) {
        i = (i + 1) % 256;
        j = (j + rc4_state[i]) % 256;
        std::swap(rc4_state[i], rc4_state[j]);
        unsigned char rc4_output = rc4_state[(rc4_state[i] + rc4_state[j]) % 256];

        user_password_bytes[k] ^= rc4_output;
    }

    // Return the resulting O value as a string
    return std::string(reinterpret_cast<char*>(user_password_bytes), data.key_length);
}

