std::string computeOValue(std::string const& user_password, std::string const& owner_password, QPDF::EncryptionData const& data) {
    // Determine the key size based on encryption data
    unsigned int key_size = data.key_size / 8;
    std::vector<unsigned char> user_pass_bytes(user_password.begin(), user_password.end());
    std::vector<unsigned char> owner_pass_bytes(owner_password.begin(), owner_password.end());

    // Truncate or pad user password to 32 bytes
    if (user_pass_bytes.size() > 32) {
        user_pass_bytes.resize(32);
    } else if (user_pass_bytes.size() < 32) {
        user_pass_bytes.resize(32, 0);
    }

    // Compute a key from the owner password
    RC4_KEY owner_key;
    RC4_set_key(&owner_key, key_size, owner_pass_bytes.data());

    // Encrypt the user password with the owner's key
    std::vector<unsigned char> encrypted_user_pass(user_pass_bytes);
    RC4(&owner_key, encrypted_user_pass.size(), encrypted_user_pass.data(), encrypted_user_pass.data());

    // Convert to hexadecimal string for O value
    std::string o_value;
    for (unsigned char byte : encrypted_user_pass) {
        char buffer[3];
        snprintf(buffer, sizeof(buffer), "%02X", byte);
        o_value += buffer;
    }

    return o_value;
}
